package com.andye.warmod.item;
import com.andye.warmod.antiair.AntiAirMissileVariant;import java.util.function.Consumer;import net.minecraft.network.chat.Component;import net.minecraft.world.item.*;import net.minecraft.world.item.component.TooltipDisplay;public final class AntiAirMissileItem extends Item {private final AntiAirMissileVariant variant;public AntiAirMissileItem(Properties p,AntiAirMissileVariant v){super(p);variant=v;}public AntiAirMissileVariant variant(){return variant;}@Override public void appendHoverText(ItemStack s,TooltipContext c,TooltipDisplay d,Consumer<Component> lines,TooltipFlag f){lines.accept(Component.literal("Interceptor missile"));lines.accept(Component.literal("Automatic target acquisition"));lines.accept(Component.literal(variant.ballisticFallback()?"Failure mode: ballistic fallback":"Failure mode: safe self-destruct"));lines.accept(Component.literal("Maximum stack: 16"));}}